// Only sync what actually changed. Comparing updated_at against synced_at is what
// keeps a 15-minute schedule from burning GHL API quota on 4,000 unchanged rows.
const SYNC_STAGES = String($env.SYNC_STAGES || 'enriched,queued,sent,replied,booked').split(',').map((s) => s.trim());
const out = [];
let skipped = 0;

for (const item of $input.all()) {
  const row = item.json;
  if (!row.email) { skipped++; continue; }
  if (SYNC_STAGES.indexOf(String(row.stage || '').trim()) === -1) { skipped++; continue; }

  const updated = Date.parse(row.updated_at || row.enriched_at || row.researched_at || '') || 0;
  const synced = Date.parse(row.synced_at || '') || 0;
  if (synced && synced >= updated) { skipped++; continue; }

  out.push({ json: Object.assign({}, row, { _skipped_this_run: skipped }) });
}

if (out.length === 0) return [];
out[0].json._skipped_this_run = skipped;
return out;

// ===================== THE NODE YOU EDIT PER CLIENT =====================
// Left side: the field name in GHL. Right side: where it comes from in our lead object.
// Anything GHL does not have a standard field for goes through GHL_CUSTOM_FIELD_MAP,
// a JSON env var of { "customFieldId": "our_field_name" }.
// =======================================================================
const STANDARD = {
  firstName: 'first_name',
  lastName: 'last_name',
  email: 'email',
  companyName: 'company',
  website: 'domain',
  city: 'city',
  country: 'country'
};

let customMap = {};
try { customMap = JSON.parse($env.GHL_CUSTOM_FIELD_MAP || '{}'); } catch (e) {
  throw new Error('GHL_CUSTOM_FIELD_MAP is not valid JSON: ' + String(e.message));
}

return $input.all().map((item) => {
  const lead = item.json;
  const contact = { locationId: $env.GHL_LOCATION_ID };

  for (const ghlField of Object.keys(STANDARD)) {
    const value = lead[STANDARD[ghlField]];
    if (value !== undefined && value !== null && String(value) !== '') contact[ghlField] = value;
  }

  contact.name = ((lead.first_name || '') + ' ' + (lead.last_name || '')).trim() || lead.email;
  contact.source = lead.built_by || 'n8n pipeline';
  contact.tags = ['pipeline', 'stage:' + (lead.stage || 'unknown')];
  if (lead.fit_score >= 70) contact.tags.push('high-fit');

  contact.customFields = Object.keys(customMap)
    .filter((id) => lead[customMap[id]] !== undefined && lead[customMap[id]] !== '')
    .map((id) => ({ id: id, value: String(lead[customMap[id]]) }));

  return { json: { _lead: lead, contact: contact } };
});

// Stamp what synced and what failed. A row that failed keeps its old synced_at, so
// the next run retries it automatically - no dead-letter queue to babysit.
const mapped = $('field map (EDIT ME)').all();
const now = new Date().toISOString();
const out = [];
let failed = 0;

for (let i = 0; i < $input.all().length; i++) {
  const res = $input.all()[i].json || {};
  const lead = (mapped[i] || { json: { _lead: {} } }).json._lead;
  const contactId = (res.contact && res.contact.id) || '';

  if (!contactId) { failed++; continue; }

  out.push({ json: {
    lead_id: lead.lead_id,
    ghl_contact_id: contactId,
    synced_at: now
  }});
}

if (out.length) out[0].json._failed = failed;
return out;

// Stay quiet when there is nothing to say. A sync that posts every 15 minutes gets
// muted by the client inside a week, and then the failures are invisible too.
const synced = $input.all().length;
const failed = Number(($input.first().json || {})._failed || 0);
if (failed === 0) return [];

return [{ json: { text: ':warning: CRM sync: ' + synced + ' contacts updated, *' + failed + ' failed*. Failed rows keep their old synced_at and retry on the next run.' } }];

// The write-back half. Whatever a human does in GHL becomes true in the Sheet, so the
// sending workflows stop mailing someone the sales rep already spoke to.
const STAGE_FROM_GHL = {
  open: 'replied',
  won: 'booked',
  lost: 'suppressed',
  abandoned: 'suppressed'
};

return $input.all().map((item) => {
  const b = item.json.body || item.json;
  const contact = b.contact || b;
  const email = String(contact.email || b.email || '').toLowerCase().trim();
  const status = String(b.status || (b.opportunity && b.opportunity.status) || '').toLowerCase();

  const patch = {
    lead_id: contact.customFields && contact.customFields.lead_id ? contact.customFields.lead_id : (b.lead_id || email),
    email: email,
    ghl_contact_id: contact.id || b.contactId || '',
    crm_owner: b.assignedTo || contact.assignedTo || '',
    updated_at: new Date().toISOString(),
    synced_at: new Date().toISOString()
  };

  if (STAGE_FROM_GHL[status]) patch.stage = STAGE_FROM_GHL[status];
  if (b.pipelineStageId) patch.crm_stage_id = b.pipelineStageId;

  return { json: patch };
});
